cd /tmp/neutrino-fast-live-b4eG5i/parallel_analysis/standard/1 && node -e '
const fs = require("fs");
const names = ["north", "south", "east", "west"];
const out = {};
for (const n of names) {
  const rows = JSON.parse(fs.readFileSync(n + ".json", "utf8"));
  if (!Array.isArray(rows)) throw new Error(n + ": expected an array");
  let units = 0, weighted = 0;
  rows.forEach((r, i) => {
    if (typeof r.units !== "number" || typeof r.weight !== "number") {
      throw new Error(n + " row " + i + ": units/weight must be numeric");
    }
    units += r.units;
    weighted += r.units * r.weight;
  });
  out[n] = { count: rows.length, units, weighted };
}
console.log(JSON.stringify(out, null, 2));
'
